function buildSection(heading, mdBody) {
  return `---\n\n## ${heading}\n\n${mdBody}`;
}

function buildLesson(lesson, nextInfo) {
  const parts = [lesson.content];
  if (lesson.exercises) parts.push(buildSection('תרגילים', lesson.exercises));
  if (lesson.project) parts.push(buildSection('פרויקט מסכם', lesson.project));
  if (nextInfo) {
    parts.push(buildSection('מה בפרק הבא', `בפרק הבא נלמד על **${nextInfo.title}** — ${nextInfo.teaser}`));
  }

  const weight = lesson.num * 10 + 1;
  const frontmatter = `---
title: "${escapeYaml(lesson.title)}"
slug: "${lesson.num}-${lesson.slug}-content"
description: "${escapeYaml(lesson.description)}"
summary: "📖 שיעור"
date: 2026-08-09T00:00:00+02:00
lastmod: 2026-08-09T00:00:00+02:00
draft: false
weight: ${weight}
toc: true
sidebar:
  collapsed: true
params:
  seo:
    title: ""
    description: ""
    canonical: ""
    robots: ""
---

`;
  const outDir = path.join(CONTENT_ROOT, lesson.category);
  fs.mkdirSync(outDir, { recursive: true });
  const fileName = `${lesson.num}-${lesson.slug}-content.md`;
  fs.writeFileSync(path.join(outDir, fileName), frontmatter + parts.join('\n\n') + '\n', 'utf8');
  console.log('wrote', path.join(lesson.category, fileName));
}

function firstSentence(md) {
  const m = md.match(/## מה זה\?\s*\n\n([^\n]+)/);
  return m ? m[1].slice(0, 200) : '';
}

(async () => {
  const byCategory = new Map();
  for (const l of lessons) {
    if (!byCategory.has(l.category)) byCategory.set(l.category, []);
    byCategory.get(l.category).push(l);
  }
  for (const list of byCategory.values()) list.sort((a, b) => a.num - b.num);

  for (const l of lessons) {
    const group = byCategory.get(l.category);
    const idx = group.indexOf(l);
    let nextInfo = null;
    if (idx < group.length - 1) {
      const n = group[idx + 1];
      nextInfo = { title: n.title, teaser: firstSentence(n.content) };
    }
    buildLesson(l, nextInfo);
  }
})();
